mapper.select:
SELECT id
FROM couple
WHERE inviter_id = #{memberId}
OR invitee_id = #{memberId}

SELECT MAX(input_version.updated_at) FROM ( SELECT member.recommendation_input_updated_at AS updated_at FROM member INNER JOIN couple ON member.id IN ( couple.inviter_id, couple.invitee_id ) WHERE couple.inviter_id = #{memberId} OR couple.invitee_id = #{memberId}
UNION ALL
SELECT personal_survey.updated_at FROM personal_survey INNER JOIN couple ON personal_survey.member_id IN ( couple.inviter_id, couple.invitee_id ) WHERE couple.inviter_id = #{memberId} OR couple.invitee_id = #{memberId}
UNION ALL
SELECT common_survey.updated_at FROM common_survey INNER JOIN invitation_code ON invitation_code.common_survey_id = common_survey.id INNER JOIN couple ON couple.invitation_code_id = invitation_code.id WHERE couple.inviter_id = #{memberId} OR couple.invitee_id = #{memberId}
UNION ALL
SELECT financial_summary.updated_at FROM financial_summary INNER JOIN couple ON financial_summary.member_id IN ( couple.inviter_id, couple.invitee_id ) WHERE couple.inviter_id = #{memberId} OR couple.invitee_id = #{memberId}
UNION ALL
SELECT pension_isa_account.updated_at FROM pension_isa_account INNER JOIN couple ON pension_isa_account.member_id IN ( couple.inviter_id, couple.invitee_id ) WHERE couple.inviter_id = #{memberId} OR couple.invitee_id = #{memberId}
UNION ALL
SELECT product.updated_at FROM product ) input_version

SELECT r.id
FROM recommendation r
INNER JOIN couple c
ON c.id = r.couple_id
WHERE c.inviter_id = #{memberId}
OR c.invitee_id = #{memberId}

mapper.insert:
INSERT INTO recommendation (
couple_id
) VALUES (
#{coupleId}
)
ON DUPLICATE KEY UPDATE
id = LAST_INSERT_ID(id),
updated_at = CURRENT_TIMESTAMP

INSERT INTO recommendation_slot (
recommendation_id,
slot_type
) VALUES (
#{recommendationId},
#{slotType}
)
